import { chromium } from "playwright-core";
import fs from "fs";
const D="<scratch>";
const b=await chromium.launch({channel:"chrome"});
const c=await b.newContext({storageState:D+"state.json",viewport:{width:375,height:812},isMobile:true,hasTouch:true,locale:"zh-TW"});
const A=await c.newPage(); await A.goto("http://192.168.31.145:8799/#/"); 
const B=await c.newPage(); await B.goto("http://192.168.31.145:8799/#/plans");
let lastA="",lastB="",n=0;
const t0=Date.now();
while(Date.now()-t0<24*60000){
  await new Promise(r=>setTimeout(r,45000)); n++;
  const ta=await A.innerText("body"), tb=await B.innerText("body");
  const el=Math.round((Date.now()-t0)/1000);
  if(ta!==lastA){lastA=ta;fs.appendFileSync(D+"log.txt",`\n=== ${el}s A (activity, no reload) CHANGED\n${ta}\n`);await A.screenshot({path:D+`A-${n}.png`,fullPage:true});}
  if(tb!==lastB){lastB=tb;fs.appendFileSync(D+"log.txt",`\n=== ${el}s B (plans) CHANGED\n${tb}\n`);await B.screenshot({path:D+`B-${n}.png`,fullPage:true});}
  fs.writeFileSync(D+"hb.txt",String(el));
  await B.reload(); await B.waitForTimeout(1500);
  if(/邀請|invit/i.test(tb)&&n>0 && !fs.existsSync(D+"STOP")) { fs.writeFileSync(D+"INVITE.txt",String(el)); break; }
}
await c.storageState({path:D+"state.json"});
await b.close();
EOF
