  const el=Math.round((Date.now()-t0)/1000);
  // no-reload check on current (activity) view
  const auto=await snap("act-noreload",el); if(auto&&n>1) fs.appendFileSync(D+"log.txt",`(auto-updated without reload at ${el}s)\n`);
  await p.goto(U+"plans"); await p.reload(); await p.waitForTimeout(2000);
  await snap("plans",el);
  await p.goto(U); await p.reload(); await p.waitForTimeout(2000);
  await snap("act-noreload",el);
  fs.writeFileSync(D+"hb.txt",String(el));
  if(fs.existsSync(D+"STOP"))break;
}
await c.storageState({path:D+"state.json"});
await b.close();
EOF
